package com.estateflow.service;
import com.estateflow.dao.*;import com.estateflow.exception.*;import com.estateflow.model.*;import com.estateflow.model.enums.*;import com.estateflow.security.*;import java.math.BigDecimal;import java.time.*;import java.util.List;
public final class WorkOrderService{
 private static final BigDecimal MAX=new BigDecimal("9999999999.99");private final WorkOrderDao dao;private final PropertyDao properties;private final VendorDao vendors;private final MaintenanceService maintenance;private final ExpenseService expenses;private final TransactionManager tx;private final AuditService audit;private final Clock clock;private final Authorizer auth;
 public WorkOrderService(WorkOrderDao dao,PropertyDao properties,VendorDao vendors,MaintenanceService maintenance,ExpenseService expenses,TransactionManager tx,AuditService audit,Clock clock,Authorizer auth){this.dao=dao;this.properties=properties;this.vendors=vendors;this.maintenance=maintenance;this.expenses=expenses;this.tx=tx;this.audit=audit;this.clock=clock;this.auth=auth;}
 public boolean isAvailable(){auth.require(Permission.VIEW_DATA);return dao.isAvailable();}
 public List<WorkOrderRow> search(Long propertyId,Long vendorId,WorkOrderStatus status,MaintenancePriority priority,LocalDate dueFrom,LocalDate dueTo,boolean overdueOnly)throws ValidationException{auth.require(Permission.VIEW_DATA);ensure();if(dueFrom!=null&&dueTo!=null&&dueTo.isBefore(dueFrom))throw new ValidationException("End date cannot be before start date.","dueTo");return dao.search(propertyId,vendorId,status,priority,dueFrom,dueTo,overdueOnly,LocalDate.now(clock));}
 public List<com.estateflow.dto.AdvancedAnalyticsReport.VendorPerformance> vendorPerformance(LocalDate completedFrom,LocalDate completedTo)throws ValidationException{auth.require(Permission.VIEW_REPORTS);if(completedFrom==null||completedTo==null||completedTo.isBefore(completedFrom))throw new ValidationException("Choose a valid work-order completion period.","dateRange");return dao.isAvailable()?dao.vendorPerformance(completedFrom,completedTo):List.of();}
 public WorkOrder get(long id)throws EntityNotFoundException{auth.require(Permission.VIEW_DATA);ensure();return dao.find(id).orElseThrow(()->new EntityNotFoundException("Work order no longer exists."));}
 public WorkOrder create(WorkOrder input)throws EstateFlowException{auth.require(Permission.MANAGE_RECORDS);ensure();WorkOrder w=validate(input);if(w.propertyId()==null||properties.findById(w.propertyId()).filter(p->p.isActive()).isEmpty())throw new ValidationException("Select an active property.","property");if(w.maintenanceRequestId()!=null){MaintenanceRequest m=maintenance.get(w.maintenanceRequestId());if(!w.propertyId().equals(m.getPropertyId()))throw new ValidationException("The maintenance request belongs to another property.","maintenanceRequest");if(m.getStatus()==MaintenanceStatus.CANCELLED)throw new BusinessRuleException("Cancelled maintenance requests cannot receive new work orders.","WO-01");}var actor=auth.require(Permission.MANAGE_RECORDS);return tx.inTransaction(()->{WorkOrder saved=dao.insert(new WorkOrder(null,w.propertyId(),w.maintenanceRequestId(),null,null,w.title(),w.scope(),w.priority(),w.dueDate(),WorkOrderStatus.DRAFT,w.estimatedCost(),null,null,actor.id(),null,null,null));audit.record("WORK_ORDER",saved.id(),"CREATED",null,AuditService.details("propertyId",saved.propertyId(),"requestId",saved.maintenanceRequestId(),"title",saved.title()));return saved;});}
 public WorkOrder update(WorkOrder input)throws EstateFlowException{auth.require(Permission.MANAGE_RECORDS);ensure();WorkOrder old=get(input==null||input.id()==null?-1:input.id());if(old.status()!=WorkOrderStatus.DRAFT&&old.status()!=WorkOrderStatus.ASSIGNED)throw new BusinessRuleException("Only draft or assigned work orders can be edited.","WO-02");WorkOrder w=validate(input);if(!old.propertyId().equals(w.propertyId()))throw new BusinessRuleException("A work order stays with its original property.","WO-03");WorkOrder next=new WorkOrder(old.id(),old.propertyId(),old.maintenanceRequestId(),old.vendorId(),old.expenseId(),w.title(),w.scope(),w.priority(),w.dueDate(),old.status(),w.estimatedCost(),old.actualCost(),old.completionNotes(),old.createdBy(),old.createdAt(),old.updatedAt(),old.completedAt());return tx.inTransaction(()->{if(dao.update(next)==0)throw new BusinessRuleException("Only draft or assigned work orders can be edited.","WO-02");audit.record("WORK_ORDER",old.id(),"UPDATED",AuditService.details("title",old.title(),"estimatedCost",old.estimatedCost()),AuditService.details("title",next.title(),"estimatedCost",next.estimatedCost()));return dao.find(old.id()).orElseThrow();});}
 public WorkOrder assign(long id,long vendorId)throws EstateFlowException{auth.require(Permission.MANAGE_RECORDS);ensure();WorkOrder old=get(id);if(old.status()!=WorkOrderStatus.DRAFT)throw new BusinessRuleException("Only draft work orders can be assigned.","WO-04");Vendor vendor=vendors.find(vendorId).filter(Vendor::active).orElseThrow(()->new BusinessRuleException("Choose an active vendor.","WO-05"));return tx.inTransaction(()->{if(dao.assign(id,vendor.id())==0)throw new BusinessRuleException("This work order changed before it could be assigned.","WO-04");audit.record("WORK_ORDER",id,"ASSIGNED",null,AuditService.details("vendorId",vendor.id()));return dao.find(id).orElseThrow();});}
 public WorkOrder transition(long id,WorkOrderStatus target,BigDecimal actual,String notes)throws EstateFlowException{auth.require(Permission.MANAGE_RECORDS);ensure();WorkOrder old=get(id);if(target==null||!old.status().canTransitionTo(target))throw new BusinessRuleException("Invalid work-order status transition from "+old.status()+" to "+target+".","WO-06");if(target==WorkOrderStatus.ASSIGNED&&old.vendorId()==null)throw new BusinessRuleException("Assign a vendor before moving this work order to Assigned.","WO-07");if(target==WorkOrderStatus.COMPLETED){money(actual,"Actual cost");String n=notes==null?"":notes.trim();if(n.length()>1000)throw new ValidationException("Completion notes cannot exceed 1000 characters.","notes");return tx.inTransaction(()->{if(dao.complete(id,old.status(),actual,n,LocalDateTime.now(clock))==0)throw new EntityNotFoundException("Work order changed before completion.");audit.record("WORK_ORDER",id,"COMPLETED",AuditService.details("status",old.status()),AuditService.details("actualCost",actual,"notes",n));return dao.find(id).orElseThrow();});}return tx.inTransaction(()->{if(dao.transition(id,old.status(),target,null,notes)==0)throw new EntityNotFoundException("Work order changed before transition.");audit.record("WORK_ORDER",id,"STATUS_CHANGED",AuditService.details("status",old.status()),AuditService.details("status",target));return dao.find(id).orElseThrow();});}
 /** Links an existing canonical expense; actual work-order costs do not independently enter NOI. */
 public WorkOrder linkExpense(long orderId,long expenseId)throws EstateFlowException{auth.require(Permission.MANAGE_RECORDS);ensure();WorkOrder w=get(orderId);if(w.status()!=WorkOrderStatus.COMPLETED)throw new BusinessRuleException("Only completed work orders can link an expense.","WO-08");if(w.expenseId()!=null)throw new BusinessRuleException("A work order already has an expense linked.","WO-09");Expense e=expenses.getForWorkOrderLink(expenseId);if(!w.propertyId().equals(e.getPropertyId()))throw new ValidationException("The expense belongs to another property.","expense");if(w.maintenanceRequestId()!=null&&!w.maintenanceRequestId().equals(e.getMaintenanceRequestId()))throw new ValidationException("The expense must be linked to the same maintenance request as the work order.","expense");if(w.actualCost()!=null&&e.getAmount().compareTo(w.actualCost())!=0)throw new ValidationException("The linked expense amount must match the work-order actual cost.","expense");return tx.inTransaction(()->{if(dao.linkExpense(orderId,expenseId)==0)throw new BusinessRuleException("An expense is already linked to this work order.","WO-09");audit.record("WORK_ORDER",orderId,"EXPENSE_LINKED",null,AuditService.details("expenseId",expenseId));return dao.find(orderId).orElseThrow();});}
 private void ensure(){if(!dao.isAvailable())throw new ConfigurationException("Vendor and work-order screens require the manual v1.7 migration db/migrations/v1.7_vendors_work_orders.sql.");}
 private static WorkOrder validate(WorkOrder w)throws ValidationException{if(w==null)throw new ValidationException("Work-order details are required.",null);String title=w.title()==null?"":w.title().trim();if(title.isEmpty()||title.length()>120)throw new ValidationException("Title is required and must be at most 120 characters.","title");String scope=trim(w.scope(),1000,"Scope"),notes=trim(w.completionNotes(),1000,"Completion notes");MaintenancePriority priority=w.priority()==null?MaintenancePriority.MEDIUM:w.priority();money(w.estimatedCost(),"Estimated cost");money(w.actualCost(),"Actual cost");return new WorkOrder(w.id(),w.propertyId(),w.maintenanceRequestId(),w.vendorId(),w.expenseId(),title,scope,priority,w.dueDate(),w.status()==null?WorkOrderStatus.DRAFT:w.status(),w.estimatedCost(),w.actualCost(),notes,w.createdBy(),w.createdAt(),w.updatedAt(),w.completedAt());}
 private static void money(BigDecimal x,String label)throws ValidationException{if(x!=null&&(x.signum()<0||x.scale()>2||x.compareTo(MAX)>0))throw new ValidationException(label+" must be non-negative and have at most two decimal places.",label.toLowerCase().replace(' ','_'));}
 private static String trim(String x,int max,String label)throws ValidationException{if(x==null||x.isBlank())return null;x=x.trim();if(x.length()>max)throw new ValidationException(label+" cannot exceed "+max+" characters.",label.toLowerCase());return x;}
}
